(function(){
 const db=V.db,mobile=typeof APPS!=='undefined',el=id=>document.getElementById(id),val=id=>el(id)?.value?.trim()||'',E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=new Intl.NumberFormat('en-US',{maximumFractionDigits:2}),money=n=>fmt.format(n)+' ج',box=()=>el(mobile?'sheet':'modal'),render=()=>mobile?draw():window.render();
 const F=window.PrototypeFlow={pending:null};
 F.snapshot=(ids=[])=>({html:box().innerHTML,fields:[...new Set([...Array.from(box().querySelectorAll('input[id],select[id],textarea[id]')).map(x=>x.id),...ids])].map(id=>({id,value:el(id)?.value,checked:el(id)?.checked,readOnly:el(id)?.readOnly}))});
 F.restore=s=>{box().innerHTML=s.html;s.fields.forEach(f=>{const x=el(f.id);if(x){x.value=f.value;x.checked=f.checked;x.readOnly=f.readOnly;}});};
 const open=V.open,close=V.close;V.open=html=>{F.pending=null;open(html);};V.close=()=>{F.pending=null;close();};
 F.review=(title,rows,note,action,ids=[],label='تأكيد وحفظ')=>{const previous=F.snapshot(ids);V.open(`<div class="pf-review"><span class="pf-symbol">✓</span><small>راجع قبل التأكيد</small><h3>${E(title)}</h3><div class="pf-summary">${rows.map(([k,v])=>`<div><span>${E(k)}</span><b>${E(v)}</b></div>`).join('')}</div><p class="pf-note">${E(note)}</p><button class="btn full" onclick="PrototypeFlow.confirm()">${E(label)}</button><button class="btn ghost full mt" onclick="PrototypeFlow.cancel()">رجوع للتعديل</button></div>`);F.pending={previous,action};};
 F.confirm=()=>{const pending=F.pending;if(!pending)return;F.pending=null;F.restore(pending.previous);return pending.action();};
 F.cancel=()=>{const pending=F.pending;if(!pending)return;F.pending=null;F.restore(pending.previous);};
 F.require=(condition,message)=>{if(!condition)throw Error(message);};
 const collect=V.collectSave;
 V.collectSave=id=>V.run(()=>{const plan=db.plans[val('vc-plan')],discount=Number(val('vc-discount')),paid=Number(val('vc-paid')),method=val('vc-method');F.require(plan,'اختار الباقة');F.require(Number.isFinite(discount)&&discount>=0&&discount<=10,'الخصم من 0 إلى 10%');const total=Math.round(plan.price*(1-discount/100));F.require(Number.isFinite(paid)&&paid>0&&paid<=total,'المبلغ المستلم لازم يكون أكبر من 0 ولا يتجاوز قيمة الاشتراك');F.require(['كاش','إنستاباي','فودافون كاش'].includes(method),'اختار طريقة الدفع');F.require(method==='كاش'||val('vc-ref'),'اكتب رقم التحويل');F.review('تأكيد تحصيل الاشتراك',[['العضو',db.member(id).name],['الباقة',plan.label],['الإجمالي بعد الخصم',money(total)],['المستلم الآن',money(paid)],['المتبقي',money(total-paid)],['طريقة الدفع',method]],paid===total?'بعد التأكيد هيتسجل الإيصال وتتفعّل حصص الباقة.':'دي دفعة جزئية. تفعيل حصص الباقة بعد استكمال المتبقي.',()=>collect(id),['vc-plan','vc-discount','vc-paid','vc-method','vc-ref'],'تأكيد المبلغ وعرض الإيصال');});
 const settle=V.settleSave;V.settleSave=id=>V.run(()=>{const invoice=db.state.invoices.find(i=>i.id===id),amount=Number(val('vs-amount')),method=val('vs-method');F.require(invoice,'الفاتورة غير موجودة');F.require(Number.isFinite(amount)&&amount>0&&amount<=invoice.total-invoice.paid,'راجع المبلغ؛ لازم يكون ضمن المتبقي');F.require(method==='كاش'||val('vs-ref'),'اكتب رقم التحويل');F.review('استكمال الدفعة',[['العضو',db.member(invoice.memberId).name],['المستلم',money(amount)],['المتبقي بعد الدفعة',money(invoice.total-invoice.paid-amount)],['الطريقة',method]],'الإيصال الجديد يرتبط بنفس الفاتورة.',()=>settle(id),['vs-amount','vs-method','vs-ref']);});
 const refund=V.refundSave;V.refundSave=id=>V.run(()=>{const tx=db.state.transactions.find(t=>t.id===id),amount=Number(val('vu-amount')),reason=val('vu-reason'),returned=db.state.transactions.filter(t=>t.originalId===id&&t.kind==='refund').reduce((n,t)=>n+t.amount,0);F.require(tx&&Number.isFinite(amount)&&amount>0&&amount<=tx.amount-returned,'راجع مبلغ الاسترداد المتاح');F.require(reason,'اكتب سبب الاسترداد');F.review('تأكيد الاسترداد',[['العضو',db.member(tx.memberId).name],['المبلغ',money(amount)],['السبب',reason]],'الاسترداد يسجل حركة مالية فقط؛ الاشتراك والحصص لا يتلغوا تلقائيًا.',()=>{const result=refund(id);if(result!==false){const last=db.state.transactions.find(t=>t.originalId===id&&t.kind==='refund'&&t.amount===amount);if(last)V.receipt(last.id);}return result;},['vu-amount','vu-reason'],'تسجيل الاسترداد');});
 const shift=Finance.closeShift;Finance.closeShift=()=>V.run(()=>{const actual=Number(val('vx-actual')),expected=db.cashExpected();F.require(val('fs-operator')&&val('fs-receiver'),'اكتب اسم المسلّم والمستلم');F.require(el('fs-confirm').checked,'أكد مراجعة وتسليم الكاش');F.require(val('vx-actual')!==''&&Number.isFinite(actual)&&actual>=0,'اكتب مبلغ الكاش الفعلي');F.require(Math.abs(actual-expected)<0.005||val('vx-note'),'اكتب سبب العجز أو الزيادة');F.review('تسليم وإقفال الوردية',[['المسلّم',val('fs-operator')],['المستلم',val('fs-receiver')],['المتوقع',money(expected)],['الفعلي',money(actual)],['الفرق',money(actual-expected)]],'بعد التأكيد يحتفظ التقرير بالتفاصيل ويبدأ درج الوردية التالية من 0.',shift,['fs-operator','fs-receiver','fs-confirm','vx-actual','vx-note',...[200,100,50,20,10,5,1].map(n=>'fs-note-'+n)],'تأكيد التسليم وعرض التقرير');});V.shiftSave=Finance.closeShift;
 const finish=V.finishSession;V.finishSession=()=>V.run(()=>{const s=db.session(V.sessionId),present=Object.values(s.present).filter(Boolean).length;F.require(s.status==='scheduled','الحصة مقفولة أو ملغاة');F.require(!s.record?.ev?.length,'احفظ نتيجة الماتش الجاري الأول');F.require(present>0,'سجّل اللاعبين الحاضرين الأول');F.review('إنهاء الحصة',[['حضور فعلي',present+' لاعبين'],['ماتشات محفوظة',s.history.length],['خصم الرصيد','حصة واحدة لكل عضو حاضر']],'راجع الحضور؛ بعد الإنهاء تتقفل الحصة ولا يمكن تكرار الخصم.',()=>{const result=finish();if(result!==false){V.close();render();toast('الحصة اتقفلت والحضور اتحفظ');}return result;},[],'تأكيد إنهاء الحصة');});
 const endMatch=V.endMatchForm;V.endMatchForm=()=>{if(!mobile||!C.rec||!C.teams)return endMatch();const r=C.rec;V.open(`<div class="pf-review"><small>راجع نتيجة الماتش</small><h3>${E(C.teams[r.a].bib[0])} × ${E(C.teams[r.b].bib[0])}</h3><div class="pf-score" dir="ltr">${r.ev.filter(e=>e.s===0).length} : ${r.ev.filter(e=>e.s===1).length}</div><p class="pf-note">لاعب الماتش: ${E(r.mvp||'ما اتختارش')}</p><button class="btn full" onclick="V.endMatch()">حفظ وإنهاء الماتش</button><button class="btn ghost full mt" onclick="V.close()">رجوع للماتش</button></div>`);};

 const receipt=V.receipt;V.receipt=id=>{receipt(id);const tx=db.state.transactions.find(t=>t.id===id);if(!tx)return;const footer=document.createElement('div');footer.className='pf-next';footer.innerHTML='<small>الخطوة الجاية</small>'+(mobile&&S.app==='manager'?'<button class="btn ghost full" onclick="Refine.profile(\''+tx.memberId+'\')">عرض ملف العضو</button><button class="btn full mt" onclick="V.close();go(\'collect\')">رجوع للتحصيل</button>':mobile?'<button class="btn ghost full" onclick="V.close();go(\'account\')">رجوع للاشتراك</button>':'<button class="btn full" onclick="V.close();go(\'billing\')">رجوع للاشتراكات والتحصيل</button>');box().appendChild(footer);};
 if(!mobile)return;
 const freeze=V.freezeSave,payment=V.paymentSave,makeup=V.makeupSave;
 V.freezeSave=()=>{const result=freeze();if(result!==false)toast('طلب التجميد اتسجل. تابع قرار الإدارة من طلباتي.');return result;};
 V.paymentSave=()=>{const result=payment();if(result!==false)toast('طلب التجديد اتسجل. الاشتراك يتفعل بعد تأكيد التحصيل.');return result;};
 V.makeupSave=()=>{const result=makeup();if(result!==false)toast('طلب التعويض اتسجل. المكان يتأكد بعد الموافقة.');return result;};
 CoachComplete.scan=()=>V.open(`<h3>تسجيل الحضور يدويًا</h3><p class="pf-note">اختار اللاعب.</p><select id="cc-scan-member">${CoachComplete.roster().map(m=>`<option value="${m.id}">${E(m.name)}</option>`).join('')}</select><button class="btn full mt" onclick="PrototypeFlow.scanSave()">تأكيد الحضور</button>`);
 F.scanSave=()=>{const result=V.attend(val('cc-scan-member'),true);if(result!==false){V.close();toast('حضور اللاعب اتسجل');}return result;};
 F.shop=()=>{const text=SHOP.map(([group,items])=>group+'\n'+items.map(i=>(M.shop[group+i[0]]?'✓ ':'□ ')+i[0]+' — '+i[1]).join('\n')).join('\n\n');V.open(`<h3>مشاركة قايمة المشتريات</h3><p class="pf-note">راجع القايمة وانزلها كنص تقدر تبعته بنفسك.</p><textarea id="pf-shopping" rows="9" readonly>${E(text)}</textarea><button class="btn full mt" onclick="PrototypeFlow.downloadShop()">تنزيل القايمة</button>`);};
 F.downloadShop=()=>Finance.download(val('pf-shopping'),'text/plain;charset=utf-8','kora-shopping.txt');
 F.weight=()=>V.run(()=>{const weight=Number(val('wt'));F.require(val('wt')!==''&&Number.isFinite(weight)&&weight>=20&&weight<=350,'اكتب وزنًا صحيحًا بين 20 و350 كجم');M.weight=weight;draw();toast('الوزن اتسجل في سجل المعاينة');});
 F.attachment=()=>{F.attachmentReturn=box().classList.contains('show')?F.snapshot():null;F.file=null;V.open(`<h3>إضافة صورة للمعاينة</h3><p class="pf-note">اختار صورة الوجبة من موبايلك.</p><input id="pf-file" type="file" accept="image/png,image/jpeg,image/webp" onchange="PrototypeFlow.previewFile(this.files[0])"><div id="pf-preview" class="pf-upload">PNG / JPG / WEBP · حتى 2 MB</div><button class="btn full" onclick="PrototypeFlow.useFile()">استخدام الصورة في المعاينة</button><button class="btn ghost full mt" onclick="PrototypeFlow.cancelFile()">رجوع</button>`);};
 F.previewFile=file=>{if(!file)return;return V.run(()=>{F.file=null;F.require(['image/png','image/jpeg','image/webp'].includes(file.type)&&file.size<=2*1024*1024,'اختار صورة PNG أو JPG أو WEBP لا تتجاوز 2 MB');const reader=new FileReader();reader.onload=()=>{F.file={name:file.name,url:reader.result};el('pf-preview').innerHTML=`<img src="${reader.result}" alt="معاينة الصورة المختارة"><small>${E(file.name)}</small>`;};reader.readAsDataURL(file);});};
 F.cancelFile=()=>{if(F.attachmentReturn)F.restore(F.attachmentReturn);else V.close();F.file=null;};
 F.useFile=()=>V.run(()=>{F.require(F.file,'اختار صورة الأول');const name=F.file.name;if(!F.attachmentReturn){F.photo=F.file;V.close();draw();if(/chat$/.test(S.scr[S.app]))el('msgIn').value='📎 صورة للمعاينة: '+name;toast('الصورة اتحددت للمعاينة؛ لم يتم رفعها');return;}F.restore(F.attachmentReturn);const notice=document.createElement('div');notice.className='pf-attachment';notice.textContent='📎 صورة مختارة للمعاينة: '+name;box().appendChild(notice);if(/chat$/.test(S.scr[S.app])){V.close();el('msgIn').value='📎 صورة للمعاينة: '+name;}toast('الصورة اتحددت للمعاينة؛ لم يتم رفعها');});
 const food=APPS.member.F.food;APPS.member.F.food=()=>food().replace("M.weight=+$('wt').value;toast('الوزن اتسجل ووصل لد. ريم')",'PrototypeFlow.weight()')+(F.photo?'<div class="pad"><div class="card"><h3>صورة الوجبة</h3><img style="max-width:100%;border-radius:14px" src="'+F.photo.url+'" alt="صورة الوجبة المختارة"><p>'+E(F.photo.name)+'</p><button class="btn ghost full" onclick="PrototypeFlow.photo=null;draw()">إزالة الصورة</button></div></div>':'');
 const originalToast=toast;toast=message=>{if(message==='القايمة اتبعتت')return F.shop();if(['الكاميرا اتفتحت','إرفاق صورة'].includes(message))return F.attachment();if(message==='خروج')return V.open('<h3>إنهاء المعاينة</h3><p class="pf-note">تقدر ترجع للرئيسية في أي وقت.</p><button class="btn full" onclick="V.close();go(\'home\')">الرجوع للرئيسية</button>');originalToast(message);el('toast').setAttribute('role','status');el('toast').setAttribute('aria-live','polite');};
 draw();
})();
